package cn.mop.api;
import cn.mop.domain.DomainException;
import cn.mop.domain.change.ChangeNoticeDraft;
import org.junit.jupiter.api.Test;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
/** Pure explicit proposal data, never substituted for approved notices, real devices or actual event matching. */
class ChangeNoticeDraftTest {
    UUID id(int n){return UUID.fromString("7d000000-0000-4000-8000-"+String.format(Locale.ROOT,"%012x",n));}
    final Instant start=Instant.parse("2026-10-04T10:00:00Z");
    ChangeNoticeDraft draft(){return new ChangeNoticeDraft(id(1),id(2),null,"合成变更😀\n只作草稿",start,null,List.of(id(3),id(4)));}
    ChangeNoticeDraft with(String summary,Instant end,List<UUID> assets){return new ChangeNoticeDraft(id(1),id(2),null,summary,start,end,assets);}
    @Test void requiredTenantApplicantSummaryStartAndAssetsAreExplicit(){assertThrows(DomainException.class,()->new ChangeNoticeDraft(null,id(2),null,"合成",start,null,List.of(id(3))));assertThrows(DomainException.class,()->new ChangeNoticeDraft(id(1),null,null,"合成",start,null,List.of(id(3))));assertThrows(DomainException.class,()->with(null,null,List.of(id(3))));assertThrows(DomainException.class,()->new ChangeNoticeDraft(id(1),id(2),null,"合成",null,null,List.of(id(3))));assertThrows(DomainException.class,()->with("合成",null,null));}
    @Test void blankSummaryCannotBecomeAnImplicitChangeDescription(){for(String s:List.of(""," \n\t\r ","\u00a0","\ufeff","\u3000"))assertThrows(DomainException.class,()->with(s,null,List.of(id(3))));}
    @Test void unicodeLimitsCountCodePointsAndDoNotTruncate(){assertEquals(4000,with("😀".repeat(2000),null,List.of(id(3))).changeSummary().length());assertThrows(DomainException.class,()->with("😀".repeat(2001),null,List.of(id(3))));}
    @Test void originalSummaryWhitespaceAndLinesArePreserved(){String s="  合成\n摘要\t ";assertEquals(s,with(s,null,List.of(id(3))).changeSummary());assertNotEquals(with(s,null,List.of(id(3))).fingerprint(),with(s.trim(),null,List.of(id(3))).fingerprint());}
    @Test void invalidControlAndSurrogateValuesAreRejectedWithoutEcho(){for(String s:List.of("SYNTHETIC_SECRET\u0000","bad\u001b","bad\u0085","\ud800","\udc00")){var e=assertThrows(DomainException.class,()->with(s,null,List.of(id(3))));assertEquals(400,e.status);assertFalse(e.getMessage().contains("SYNTHETIC_SECRET"));}}
    @Test void noDeviceSelectionIsNotAllDevicesOrAnEmptyEffectiveNotice(){assertThrows(DomainException.class,()->with("合成",null,List.of()));assertThrows(DomainException.class,()->with("合成",null,Arrays.asList((UUID)null)));}
    @Test void repeatedTargetsAreRejectedNotSilentlyDeduplicated(){assertThrows(DomainException.class,()->with("合成",null,List.of(id(3),id(3))));}
    @Test void technicalTargetLimitRejectsInsteadOfTruncating(){var ids=new ArrayList<UUID>();for(int n=1;n<=1000;n++)ids.add(id(n));assertEquals(1000,with("合成",null,ids).assetIds().size());ids.add(id(1001));assertEquals(413,assertThrows(DomainException.class,()->with("合成",null,ids)).status);}
    @Test void targetsAreDetachedOrderedAndImmutable(){var ids=new ArrayList<>(List.of(id(4),id(3)));var d=with("合成",null,ids);ids.clear();assertEquals(List.of(id(4),id(3)),d.assetIds());assertThrows(UnsupportedOperationException.class,()->d.assetIds().clear());}
    @Test void unknownEndStaysNullWithoutDefaultDurationOrMatching(){assertNull(draft().plannedEndAt());assertNull(draft().plannedBusinessEndDate());assertNull(draft().automaticP3Decision());assertEquals("CONFIG_PENDING",draft().matchingPolicyStatus());}
    @Test void explicitlySuppliedEndMustBeStrictlyLater(){for(Instant end:List.of(start,start.minusMillis(1)))assertThrows(DomainException.class,()->with("合成",end,List.of(id(3))));assertEquals(start.plusMillis(1),with("合成",start.plusMillis(1),List.of(id(3))).plannedEndAt());}
    @Test void inputInstantsCannotLoseSubmillisecondPrecision(){assertThrows(DomainException.class,()->new ChangeNoticeDraft(id(1),id(2),null,"合成",start.plusNanos(1),null,List.of(id(3))));assertThrows(DomainException.class,()->with("合成",start.plusSeconds(1).plusNanos(1),List.of(id(3))));}
    @Test void bothUtcAndBusinessCalendarYearsMustBeRepresentable(){for(Instant t:List.of(Instant.MIN,Instant.MAX,Instant.parse("9999-12-31T16:00:00Z")))assertThrows(DomainException.class,()->new ChangeNoticeDraft(id(1),id(2),null,"合成",t,null,List.of(id(3))));assertDoesNotThrow(()->new ChangeNoticeDraft(id(1),id(2),null,"合成",Instant.parse("0001-01-01T00:00:00Z"),Instant.parse("9999-12-31T15:59:59.999Z"),List.of(id(3))));}
    @Test void futureAndHistoricalPlannedTimesDoNotAssertExecutionOrEmergencyApproval(){for(Instant time:List.of(Instant.parse("2000-01-01T00:00:00Z"),Instant.parse("2035-01-01T00:00:00Z"))){var d=new ChangeNoticeDraft(id(1),id(2),null,"合成",time,null,List.of(id(3)));assertEquals(time,d.plannedStartAt());assertFalse(d.deviceExecutionAllowed());assertNull(d.approvalStatus());assertFalse(d.effective());}}
    @Test void businessDateUsesContractFixedShanghaiNotSystemClock(){var d=new ChangeNoticeDraft(id(1),id(2),null,"合成",Instant.parse("2026-10-04T15:59:59.999Z"),Instant.parse("2026-10-04T16:00:00Z"),List.of(id(3)));assertEquals("Asia/Shanghai",d.timezone());assertEquals(LocalDate.of(2026,10,4),d.plannedBusinessStartDate());assertEquals(LocalDate.of(2026,10,5),d.plannedBusinessEndDate());}
    @Test void optionalTicketReferenceIsNotExistenceOrAuthorizationProof(){assertNull(draft().ticketId());var d=new ChangeNoticeDraft(id(1),id(2),id(9),draft().changeSummary(),start,null,draft().assetIds());assertEquals(id(9),d.ticketId());assertEquals("NOT_VERIFIED_BY_THIS_MODEL",d.referenceVerification());assertNotEquals(draft().fingerprint(),d.fingerprint());}
    @Test void scopeComparisonRejectsForeignTenantWithoutRebinding(){assertDoesNotThrow(()->draft().requireTenant(id(1)));assertEquals(404,assertThrows(DomainException.class,()->draft().requireTenant(id(9))).status);assertEquals(400,assertThrows(DomainException.class,()->draft().requireTenant(null)).status);}
    @Test void knownWindowAndApplicantCannotGrantApprovalOrSuppressAlerts(){for(Instant end:Arrays.asList(null,start.plusSeconds(3600))){var d=with("合成",end,List.of(id(3)));assertEquals("DRAFT",d.lifecycleStatus());assertEquals("UNREVIEWED_CHANGE_NOTICE_DRAFT",d.recordSource());assertEquals("CONFIG_PENDING",d.approvalWorkflowStatus());assertNull(d.approvalStatus());assertFalse(d.approvalEvidenceVerified());assertFalse(d.alertSuppressionAllowed());assertFalse(d.deviceExecutionAllowed());assertFalse(d.effective());assertNull(d.automaticP3Decision());}}
    @Test void canonicalEncodingMatchesIndependentPythonGolden(){assertEquals(243,draft().canonicalBytes().length);assertEquals("36e3b2c1427636355944e0a1e256b0305a82946add4498e036246f4d0165f3be",draft().fingerprint());}
    @Test void canonicalBytesAreFreshAndCannotMutateModel(){var a=draft().canonicalBytes();a[0]=99;assertNotEquals(99,draft().canonicalBytes()[0]);assertEquals("36e3b2c1427636355944e0a1e256b0305a82946add4498e036246f4d0165f3be",draft().fingerprint());}
    @Test void fingerprintBindsTenantApplicantSummaryTimeTicketAndOrderedTargets(){var d=draft();var changes=List.of(new ChangeNoticeDraft(id(9),id(2),null,d.changeSummary(),start,null,d.assetIds()),new ChangeNoticeDraft(id(1),id(9),null,d.changeSummary(),start,null,d.assetIds()),new ChangeNoticeDraft(id(1),id(2),id(9),d.changeSummary(),start,null,d.assetIds()),new ChangeNoticeDraft(id(1),id(2),null,d.changeSummary(),start.plusMillis(1),null,d.assetIds()),with("不同摘要",null,d.assetIds()),with(d.changeSummary(),start.plusMillis(1),d.assetIds()),with(d.changeSummary(),null,List.of(id(4),id(3))));for(var changed:changes)assertNotEquals(d.fingerprint(),changed.fingerprint());}
}
